function skuFrequency(rows: Array<Record<string, unknown>>) {
  const result = new Map<string, number>();
  for (const row of rows) {
    const sku = typeof row.sku === "string" ? row.sku.trim() : "";
    if (sku) result.set(sku, (result.get(sku) || 0) + 1);
  }
  return result;
}

function frequency(rows: Array<Record<string, unknown>>, key: string) {
  const result = new Map<string, number>();
  for (const row of rows) {
    const value = typeof row[key] === "string" ? String(row[key]).trim() : "";
    if (value) result.set(value, (result.get(value) || 0) + 1);
  }
  return result;
}

function productImageRole(value: unknown, isCover: unknown, sortOrder: unknown): ProductImageRole {
  if (PRODUCT_IMAGE_ROLES.includes(value as ProductImageRole)) return value as ProductImageRole;
  if (isCover === true) return "front";
  return PRODUCT_IMAGE_ROLES[Math.max(0, Math.min(3, Number(sortOrder || 0)))] || "lifestyle";
}

function asRecord(value: unknown): Record<string, unknown> {
  return typeof value === "object" && value !== null ? value as Record<string, unknown> : {};
}

function asRecordArray(value: unknown): Record<string, unknown>[] {
  return Array.isArray(value) ? value.filter((item) => typeof item === "object" && item !== null) as Record<string, unknown>[] : [];
}

const PRODUCT_AUDIT_FIELDS = ["name", "slug", "product_category_id", "product_subcategory_id", "base_price", "sku", "status", "product_type", "pricing_mode", "sales_mode", "minimum_order_qty"] as const;
const VARIANT_AUDIT_FIELDS = ["name", "slug", "sku", "price_adjustment", "status", "is_active", "sort_order"] as const;
const SELLABLE_AUDIT_FIELDS = ["size_id", "size_name", "sku", "stock_quantity", "price_adjustment", "status", "is_active", "sort_order"] as const;

async function loadAuditRow(client: SupabaseClient, table: string, id: string, fields: readonly string[]) {
  const { data, error } = await client.from(table).select(["id", ...fields].join(",")).eq("id", id).maybeSingle();
  if (error || !data) return null;
  return asRecord(data);
}

async function auditProductMutation(input: {
  actor: Awaited<ReturnType<typeof requireProductActor>>;
  identity: ReturnType<typeof createPimAuditIdentity>;
  eventCode: PimAuditEventCode;
  status?: PimAuditStatus;
  entityType: string;
  entityId?: string | null;
  entityLabel?: string | null;
  productId?: string | null;
  variantId?: string | null;
  sku?: string | null;
  before?: Record<string, unknown> | null;
  after?: Record<string, unknown> | null;
  fields?: readonly string[];
  failureCode?: string | null;
  metadata?: Record<string, unknown>;
}) {
  const status = input.status || "COMPLETED";
  const changes = diffPimAuditFields(input.before || null, input.after || null, input.fields || []);
  await recordPimAuditEvent(input.actor.adminClient, {
    eventCode: input.eventCode,
    status,
    actorId: input.actor.user.id,
    actorRole: input.actor.role,
    actorLabel: actorAuditLabel(input.actor.user),
    requestId: input.identity.requestId,
    operationId: input.identity.operationId,
    idempotencyKey: input.identity.idempotencyKey,
    entityType: input.entityType,
    entityId: input.entityId,
    entityLabel: input.entityLabel,
    productId: input.productId,
    variantId: input.variantId,
    sku: input.sku,
    summary: PIM_AUDIT_EVENT_REGISTRY[input.eventCode].label,
    failureCode: input.failureCode,
    changes,
    metadata: { ...input.metadata, changedFields: changes.map((change) => change.field) },
    entities: [{
      entityType: input.entityType,
      entityId: input.entityId || null,
      entityLabel: input.entityLabel,
      productId: input.productId,
      variantId: input.variantId,
      sku: input.sku,
      resultStatus: status,
      failureCode: input.failureCode
    }]
  });
}

function variantEvent(before: Record<string, unknown> | null, after: Record<string, unknown> | null): PimAuditEventCode {
  if (!before) return "VARIANT_CREATED";
  if (before.sku !== after?.sku) return "VARIANT_SKU_CHANGED";
  if (before.stock_quantity !== after?.stock_quantity) return "VARIANT_STOCK_CHANGED";
  if (before.price_adjustment !== after?.price_adjustment) return "VARIANT_PRICE_CHANGED";
  if (before.size_id !== after?.size_id) return "VARIANT_SIZE_CHANGED";
  if (before.name !== after?.name || before.slug !== after?.slug) return "VARIANT_COLOR_CHANGED";
  if (before.status !== after?.status || before.is_active !== after?.is_active) return "VARIANT_STATUS_CHANGED";
  return "VARIANT_UPDATED";
}

function productEvent(before: Record<string, unknown> | null, after: Record<string, unknown> | null): PimAuditEventCode {
  if (!before) return "PRODUCT_CREATED";
  if (before.product_category_id !== after?.product_category_id) return "PRODUCT_CATEGORY_CHANGED";
  if (before.status !== after?.status) return "PRODUCT_STATUS_CHANGED";
  return "PRODUCT_UPDATED";
}

function textValue(value: unknown) {
  return typeof value === "string" && value ? value : null;
}

async function readBody(request: Request): Promise<ActionBody> {
  try {
    const body = await request.json();
    return typeof body === "object" && body !== null ? body as ActionBody : {};
  } catch {
    throw new ProductApiError(400, "JSON request tidak valid.");
  }
}

function cleanId(value: unknown) {
  return typeof value === "string" && /^[0-9a-f-]{36}$/i.test(value) ? value : "";
}
function compatibilityUpdatedAt(value: unknown) {
  if (value === null) return null;
  if (typeof value === "string" && value.trim()) return value.trim();
  throw new ProductApiError(400, "Product version compatibility path tidak valid.");
}
function compatibilityReviewVersion(value: unknown) {
  if (typeof value === "string" && /^wp07-[0-9a-f]{8}$/.test(value)) return value;
  throw new ProductApiError(400, "Review version compatibility path tidak valid.");
}
function lifecycle(value: unknown): ProductLifecycle {
  return value === "active" || value === "archived" ? value : "draft";
}
function variantStatus(value: unknown, legacyActive: unknown): "active" | "inactive" {
  if (value === "inactive" || legacyActive === false) return "inactive";
  return "active";
}
function finiteNumber(value: unknown) {
  if (value === null || value === undefined || value === "") return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}
function validationResponse(issues: ValidationIssue[]) {
  return noStoreJson({ ok: false, issues, error: "Validasi Draft gagal." }, 422);
}
function noStoreJson(body: unknown, status = 200) {
  return NextResponse.json(body, { status, headers: { "cache-control": "private, no-store" } });
}

class ProductApiError extends Error {
  constructor(public readonly status: number, message: string) {
    super(message);
  }
}

function productErrorResponse(error: unknown) {
  const guestResponse = adminGuestErrorResponse(error);
  if (guestResponse) return guestResponse;
  if (error instanceof VariantMatrixServerError) {
    return noStoreJson({ error: error.message, issues: error.issues }, error.status);
  }
  if (
    error instanceof ProductApiError ||
    error instanceof ProductReviewApiError ||
    error instanceof Phase13AuthError
  ) {
    return noStoreJson({ error: error.message }, error.status);
  }
  console.error("Product Manager API failed", { error: error instanceof Error ? error.name : "unknown" });
  return noStoreJson({ error: "Operasi Unified Product Manager gagal diproses." }, 500);
}

