  const [notice, setNotice] = useState("");
  const [activeRun, setActiveRun] = useState<RunSummary | null>(null);
  const [findings, setFindings] = useState<FindingPage>({ page: 1, pageSize: 50, total: 0, rows: [] });
  const [findingPage, setFindingPage] = useState(1);
  const [findingSeverity, setFindingSeverity] = useState("all");
  const [findingLifecycle, setFindingLifecycle] = useState("all");
  const [findingQuery, setFindingQuery] = useState("");
  const [findingFilters, setFindingFilters] = useState<FindingFilters>(emptyFindingFilters);
  const [exportToken, setExportToken] = useState(() => createToken("export"));
  const [reconciliationToken, setReconciliationToken] = useState(() => createToken("reconcile"));

  const loadConfig = useCallback(async () => {
    const response = await authorizedFetch("/api/admin/products/export-reconciliation");
    const payload = await response.json() as Config & { error?: string };
    if (!response.ok) throw new Error("Konfigurasi ekspor belum dapat dimuat.");
    setConfig(payload);
  }, []);

  const loadProducts = useCallback(async () => {
    setLoading(true);
    const params = new URLSearchParams({ view: "products", page: String(page), query: filters.query, status: filters.status });
    if (filters.categoryId) params.set("categoryId", filters.categoryId);
    if (filters.updatedFrom) params.set("updatedFrom", filters.updatedFrom.slice(0, 10));
    if (filters.updatedTo) params.set("updatedTo", filters.updatedTo.slice(0, 10));
    try {
      const response = await authorizedFetch(`/api/admin/products/export-reconciliation?${params}`);
      const payload = await response.json() as ProductPage & { error?: string };
      if (!response.ok) throw new Error("Daftar produk belum dapat dimuat.");
      setProducts(payload);
    } catch {
      setNotice("Daftar produk belum dapat dimuat. Coba lagi.");
    } finally {
      setLoading(false);
    }
  }, [filters, page]);

  useEffect(() => { void loadConfig().catch(() => setNotice("Pengaturan ekspor belum dapat dimuat. Coba lagi.")); }, [loadConfig]);
  useEffect(() => { const timer = window.setTimeout(() => void loadProducts(), 200); return () => window.clearTimeout(timer); }, [loadProducts]);

  const scope = useMemo<PimPhase6Scope>(() => ({
    kind: scopeKind,
    ids: scopeKind === "current_page" ? products.rows.filter((row) => selectedIds.has(row.id)).map((row) => row.id) : [...selectedIds],
    excludedIds: scopeKind === "all_matching" ? [...excludedIds] : [],
    filters
  }), [excludedIds, filters, products.rows, scopeKind, selectedIds]);
  const selectedOnPage = products.rows.filter((row) => scopeKind === "all_matching" ? !excludedIds.has(row.id) : selectedIds.has(row.id)).length;
  const pageChecked = Boolean(products.rows.length) && selectedOnPage === products.rows.length;
  const totalPages = Math.max(1, Math.ceil(products.total / products.pageSize));

  function changeFilters(next: PimPhase6Filters) {
    setFilters(next);
    setPage(1);
    setSelectedIds(new Set());
    setExcludedIds(new Set());
    setEstimate(null);
    setExportToken(createToken("export"));
    setReconciliationToken(createToken("reconcile"));
  }

  function changeScope(next: PimPhase6ScopeKind) {
    setScopeKind(next);
    setSelectedIds(new Set());
    setExcludedIds(new Set());
    setEstimate(null);
    setExportToken(createToken("export"));
    setReconciliationToken(createToken("reconcile"));
    if (next === "full") setFilters(emptyFilters);
  }

  function toggleRow(id: string, checked: boolean) {
    setEstimate(null);
    if (scopeKind === "all_matching") setExcludedIds((current) => { const next = new Set(current); if (checked) next.delete(id); else if (next.size < (config?.limits.maxExclusions || 1000)) next.add(id); return next; });
    else setSelectedIds((current) => { const next = new Set(current); if (checked) next.add(id); else next.delete(id); return next; });
  }

  function togglePage(checked: boolean) {
    setEstimate(null);
    if (scopeKind === "all_matching") setExcludedIds((current) => { const next = new Set(current); for (const row of products.rows) checked ? next.delete(row.id) : next.add(row.id); return next; });
    else setSelectedIds((current) => { const next = new Set(current); for (const row of products.rows) checked ? next.add(row.id) : next.delete(row.id); return next; });
  }

  async function estimateScope() {
    setWorking(true);
    setNotice("Menghitung ulang cakupan data...");
    try {
      const response = await phase6Post({ action: "estimate", scope });
      const payload = await response.json() as Estimate & { error?: string; code?: string };
      if (!response.ok) throw new Error("Cakupan data belum dapat dihitung. Persempit pilihan lalu coba lagi.");
      setEstimate(payload);
      setNotice(payload.mode === "DIRECT" ? "Cakupan siap diproses." : "Cakupan melebihi batas. Persempit filter sebelum melanjutkan.");
    } catch {
      setEstimate(null);
      setNotice("Cakupan data belum dapat dihitung. Persempit pilihan lalu coba lagi.");
    } finally {
      setWorking(false);
    }
  }

  async function generateExport() {
    if (!estimate || estimate.mode !== "DIRECT") return;
    setWorking(true);
    setNotice("Menyiapkan data ekspor dan menyimpan file pribadi...");
    try {
      const response = await phase6Post({ action: "export", scope, format, idempotencyToken: exportToken });
      const payload = await response.json() as { job?: ExportJob; downloadPath?: string | null; error?: string; code?: string };
      if (!response.ok || !payload.job) throw new Error("Ekspor belum dapat dibuat. Periksa pilihan lalu coba lagi.");
      setNotice(`Ekspor ${exportStatusLabel(payload.job.status)}. SHA-256: ${payload.job.fileSha256 || "menunggu"}`);
      await loadConfig();
      if (payload.downloadPath) await downloadPrivateFile(payload.downloadPath, payload.job.fileName || undefined);
      setExportToken(createToken("export"));
    } catch {
      setNotice("Ekspor belum dapat dibuat. Periksa pilihan lalu coba lagi.");
    } finally {
      setWorking(false);
    }
  }

  async function runReconciliation() {
    if (!estimate || estimate.mode !== "DIRECT") return;
    setWorking(true);
    setNotice("Menjalankan pemeriksaan data tanpa melakukan perubahan...");
    try {
      const response = await phase6Post({ action: "reconcile", scope, idempotencyToken: reconciliationToken });
      const payload = await response.json() as { run?: RunSummary; findings?: FindingPage; error?: string; code?: string };
      if (!response.ok || !payload.run) throw new Error("Pemeriksaan data belum dapat dijalankan. Coba lagi.");
      setActiveRun(payload.run);
      setFindings(payload.findings || { page: 1, pageSize: 50, total: 0, rows: [] });
      setFindingPage(1);
      setNotice(`Pemeriksaan ${runStatusLabel(payload.run.status)} · ${payload.run.totalFindings} temuan · ${completenessLabel(payload.run.completeness)}.`);
      await loadConfig();
      setReconciliationToken(createToken("reconcile"));
    } catch {
      setNotice("Pemeriksaan data belum dapat dijalankan. Coba lagi.");
    } finally {
      setWorking(false);
    }
  }

  const loadFindings = useCallback(async () => {
    if (!activeRun) return;
    const params = new URLSearchParams({ view: "findings", runId: activeRun.id, page: String(findingPage), query: findingQuery });
    if (findingSeverity !== "all") params.set("severity", findingSeverity);
    if (findingLifecycle !== "all") params.set("lifecycle", findingLifecycle);
    for (const [key, value] of Object.entries(findingFilters)) if (value && value !== "all") params.set(key, value);
    const response = await authorizedFetch(`/api/admin/products/export-reconciliation?${params}`);
    const payload = await response.json() as FindingPage & { error?: string };
    if (!response.ok) throw new Error("Temuan belum dapat dimuat. Coba lagi.");
    setFindings(payload);
  }, [activeRun, findingFilters, findingLifecycle, findingPage, findingQuery, findingSeverity]);

  useEffect(() => { const timer = window.setTimeout(() => void loadFindings().catch(() => setNotice("Temuan belum dapat dimuat. Coba lagi.")), 200); return () => window.clearTimeout(timer); }, [loadFindings]);

  async function createReport(reportFormat: "xlsx" | "csv") {
    if (!activeRun || activeRun.completeness !== "COMPLETE") return;
    setWorking(true);
    try {
      const response = await phase6Post({ action: "report", runId: activeRun.id, format: reportFormat, idempotencyToken: `report_${reportFormat}_${activeRun.id.replace(/-/g, "")}` });
      const payload = await response.json() as { job?: ExportJob; downloadPath?: string | null; error?: string; code?: string };
      if (!response.ok || !payload.job) throw new Error("Laporan belum dapat dibuat. Coba lagi.");
      setNotice(`Laporan ${reportFormat.toUpperCase()} siap. SHA-256: ${payload.job.fileSha256 || "—"}`);
      await loadConfig();
      if (payload.downloadPath) await downloadPrivateFile(payload.downloadPath, payload.job.fileName || undefined);
    } catch (error) {
      setNotice("Laporan belum dapat dibuat. Coba lagi.");
    } finally {
      setWorking(false);
    }
  }

  return <div className="grid gap-6">
    <AdminPageHeader eyebrow="MANAJEMEN PRODUK" title="Ekspor & Pemeriksaan Data" description="Ekspor data PIM dan periksa kelengkapan data tanpa mengubah produk. Setiap temuan mengarah ke halaman edit yang sesuai." actions={<Link href="/admin/products" className="rounded-full border border-brand-softGray bg-white px-5 py-3 text-sm font-semibold">Kembali ke Manajemen Produk</Link>} />
    <div role="status" className="border border-emerald-200 bg-emerald-50 px-5 py-4 text-sm font-semibold text-emerald-900">MODE LIHAT SAJA — ekspor dan pemeriksaan tidak mengubah produk, varian, SKU, harga, stok, status, data referensi, atau media.</div>
    <div aria-live="polite" className="min-h-6 text-sm font-medium">{notice}</div>

    <div role="tablist" aria-label="Ekspor dan pemeriksaan data" className="flex gap-2 border-b border-brand-softGray">
      <button role="tab" aria-selected={tab === "export"} type="button" onClick={() => setTab("export")} className={`min-h-11 border-b-2 px-5 text-sm font-semibold ${tab === "export" ? "border-brand-green text-brand-green" : "border-transparent"}`}>Ekspor Produk</button>
      <button role="tab" aria-selected={tab === "reconciliation"} type="button" onClick={() => setTab("reconciliation")} className={`min-h-11 border-b-2 px-5 text-sm font-semibold ${tab === "reconciliation" ? "border-brand-green text-brand-green" : "border-transparent"}`}>Pemeriksaan Data</button>
    </div>

    <section className="border border-brand-softGray bg-white p-5 sm:p-6" aria-labelledby="scope-heading">
      <h2 id="scope-heading" className="text-lg font-semibold">1. Pilih Cakupan</h2>
      <div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        <label className="text-sm font-semibold">Cakupan<select value={scopeKind} onChange={(event) => changeScope(event.target.value as PimPhase6ScopeKind)} className="mt-2 min-h-11 w-full border bg-white px-3 font-normal"><option value="selected">Produk yang Dipilih</option><option value="current_page">Pilihan pada Halaman Ini</option><option value="all_matching">Semua Hasil Filter</option><option value="category">Kategori</option><option value="status">Status Produk</option><option value="updated_range">Rentang Tanggal Pembaruan</option><option value="full">Seluruh Data PIM</option></select></label>
        <label className="text-sm font-semibold">Cari produk<input value={filters.query} disabled={scopeKind === "full"} onChange={(event) => changeFilters({ ...filters, query: event.target.value })} className="mt-2 min-h-11 w-full border px-3 font-normal disabled:bg-brand-offWhite" placeholder="Nama, slug, SKU" /></label>
        <label className="text-sm font-semibold">Status<select value={filters.status} disabled={scopeKind === "full"} onChange={(event) => changeFilters({ ...filters, status: event.target.value as PimPhase6Filters["status"] })} className="mt-2 min-h-11 w-full border bg-white px-3 font-normal disabled:bg-brand-offWhite"><option value="all">Semua status</option><option value="draft">Draft</option><option value="active">Aktif</option><option value="archived">Diarsipkan</option></select></label>
        <label className="text-sm font-semibold">Kategori<select value={filters.categoryId || ""} disabled={scopeKind === "full"} onChange={(event) => changeFilters({ ...filters, categoryId: event.target.value || null })} className="mt-2 min-h-11 w-full border bg-white px-3 font-normal disabled:bg-brand-offWhite"><option value="">Semua kategori</option>{(config?.categories || []).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
        <label className="text-sm font-semibold">Diperbarui mulai<input type="date" value={filters.updatedFrom?.slice(0, 10) || ""} disabled={scopeKind === "full"} onChange={(event) => changeFilters({ ...filters, updatedFrom: event.target.value || null })} className="mt-2 min-h-11 w-full border px-3 font-normal disabled:bg-brand-offWhite" /></label>
        <label className="text-sm font-semibold">Diperbarui sampai<input type="date" value={filters.updatedTo?.slice(0, 10) || ""} disabled={scopeKind === "full"} onChange={(event) => changeFilters({ ...filters, updatedTo: event.target.value || null })} className="mt-2 min-h-11 w-full border px-3 font-normal disabled:bg-brand-offWhite" /></label>
      </div>

      <div className="mt-5 overflow-x-auto border"><table className="min-w-[820px] w-full text-left text-sm"><thead className="bg-brand-offWhite"><tr><th className="w-14 px-4 py-3"><input type="checkbox" checked={pageChecked} onChange={(event) => togglePage(event.target.checked)} aria-label="Pilih seluruh produk pada halaman ini" className="h-5 w-5" /></th><th className="px-4 py-3">Produk</th><th className="px-4 py-3">Kategori</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Harga dasar</th><th className="px-4 py-3">Diperbarui</th></tr></thead><tbody>{loading ? <tr><td colSpan={6} className="p-8 text-center">Memuat produk...</td></tr> : products.rows.length ? products.rows.map((row) => { const checked = scopeKind === "all_matching" ? !excludedIds.has(row.id) : selectedIds.has(row.id); return <tr key={row.id} className="border-t"><td className="px-4 py-3"><input type="checkbox" checked={checked} disabled={["category", "status", "updated_range", "full"].includes(scopeKind)} onChange={(event) => toggleRow(row.id, event.target.checked)} aria-label={`Pilih ${row.name}`} className="h-5 w-5 disabled:opacity-30" /></td><td className="px-4 py-3"><strong>{row.name}</strong><p className="text-xs text-brand-charcoal/50">/{row.slug}</p></td><td className="px-4 py-3">{row.categoryName}</td><td className="px-4 py-3">{productStatusLabel(row.status)}</td><td className="px-4 py-3">{row.basePrice ?? "—"}</td><td className="px-4 py-3 text-xs">{row.updatedAt ? new Date(row.updatedAt).toLocaleString("id-ID") : "—"}</td></tr>; }) : <tr><td colSpan={6} className="p-8 text-center">Tidak ada produk pada filter ini.</td></tr>}</tbody></table></div>
      <div className="mt-4 flex flex-wrap items-center justify-between gap-3"><p className="text-sm">{scopeKind === "all_matching" ? `${Math.max(0, products.total - excludedIds.size)} hasil filter dipilih · ${excludedIds.size} dikecualikan` : `${selectedIds.size} produk dipilih · ${products.total} hasil filter`}</p><div className="flex items-center gap-2"><button type="button" onClick={() => setPage((value) => Math.max(1, value - 1))} disabled={page <= 1} className="rounded-full border px-4 py-2 text-xs font-semibold disabled:opacity-40">Sebelumnya</button><span className="text-xs font-semibold">{page}/{totalPages}</span><button type="button" onClick={() => setPage((value) => Math.min(totalPages, value + 1))} disabled={page >= totalPages} className="rounded-full border px-4 py-2 text-xs font-semibold disabled:opacity-40">Berikutnya</button></div></div>
    </section>

    <section className="border border-brand-softGray bg-white p-5 sm:p-6" aria-labelledby="summary-heading"><h2 id="summary-heading" className="text-lg font-semibold">2. Tinjau Cakupan</h2><div className="mt-4 flex flex-wrap gap-3"><button type="button" onClick={estimateScope} disabled={working} className="min-h-11 rounded-full bg-brand-charcoal px-6 text-sm font-semibold text-white disabled:opacity-40">Hitung Ulang Cakupan</button>{tab === "export" ? <label className="text-sm font-semibold">Format<select value={format} onChange={(event) => { setFormat(event.target.value as "xlsx" | "csv"); setExportToken(createToken("export")); }} className="ml-2 min-h-11 border bg-white px-3 font-normal"><option value="xlsx">XLSX</option><option value="csv">CSV UTF-8</option></select></label> : null}</div>{estimate ? <div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-5">{[["Cakupan", estimate.scopeLabel], ["Produk", estimate.productCount], ["Varian/SKU", estimate.variantCount], ["Metode pemrosesan", estimateModeLabel(estimate.mode)], [tab === "export" ? "Versi format" : "Versi aturan", tab === "export" ? estimate.schemaVersion : estimate.ruleSetVersion]].map(([label, value]) => <div key={String(label)} className="border p-3"><p className="text-xs text-brand-charcoal/50">{label}</p><p className="mt-1 break-words text-sm font-semibold">{value}</p></div>)}</div> : null}<p className="mt-4 text-xs text-brand-charcoal/55">Batas pemrosesan langsung: {config?.limits.directProducts || 250} produk / {config?.limits.directVariants || 5000} varian · file tersedia selama {config?.limits.retentionHours || 168} jam. Persempit cakupan jika batas terlampaui.</p></section>

    {tab === "export" ? <ExportPanel config={config} estimate={estimate} working={working} onGenerate={generateExport} onDownload={downloadPrivateFile} /> : <ReconciliationPanel activeRun={activeRun} findings={findings} findingPage={findingPage} findingSeverity={findingSeverity} findingLifecycle={findingLifecycle} findingQuery={findingQuery} findingFilters={findingFilters} working={working} estimate={estimate} config={config} onRun={runReconciliation} onOpenRun={(run) => { setActiveRun(run); setFindingPage(1); }} onFindingPage={setFindingPage} onSeverity={(value) => { setFindingSeverity(value); setFindingPage(1); }} onLifecycle={(value) => { setFindingLifecycle(value); setFindingPage(1); }} onQuery={(value) => { setFindingQuery(value); setFindingPage(1); }} onFindingFilters={(value) => { setFindingFilters(value); setFindingPage(1); }} onReport={createReport} />}
  </div>;
}

function ExportPanel({ config, estimate, working, onGenerate, onDownload }: { config: Config | null; estimate: Estimate | null; working: boolean; onGenerate: () => void; onDownload: (path: string, name?: string) => Promise<void> }) {
  return <section role="tabpanel" className="border border-brand-softGray bg-white p-5 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">3. Buat Ekspor Produk</h2><p className="mt-1 text-sm text-brand-charcoal/55">XLSX berisi informasi, kamus data, produk, varian, dan data referensi. CSV memakai satu baris untuk setiap SKU yang dapat dijual.</p></div><button type="button" onClick={onGenerate} disabled={working || estimate?.mode !== "DIRECT"} className="min-h-11 rounded-full bg-brand-green px-6 text-sm font-semibold text-white disabled:opacity-40">Buat & Unduh</button></div><HistoryList rows={config?.exportHistory.filter((item) => item.jobKind === "product_export") || []} available={Boolean(config?.exportHistoryAvailable)} onDownload={onDownload} /></section>;
}

function ReconciliationPanel(props: { activeRun: RunSummary | null; findings: FindingPage; findingPage: number; findingSeverity: string; findingLifecycle: string; findingQuery: string; findingFilters: FindingFilters; working: boolean; estimate: Estimate | null; config: Config | null; onRun: () => void; onOpenRun: (run: RunSummary) => void; onFindingPage: (page: number) => void; onSeverity: (value: string) => void; onLifecycle: (value: string) => void; onQuery: (value: string) => void; onFindingFilters: (value: FindingFilters) => void; onReport: (format: "xlsx" | "csv") => void }) {
  const totalPages = Math.max(1, Math.ceil(props.findings.total / props.findings.pageSize));
  const [runStatus, setRunStatus] = useState("all");
  const visibleRuns = (props.config?.runHistory || []).filter((run) => runStatus === "all" || run.status === runStatus);
  const runSummary = props.activeRun ? [["Status", runStatusLabel(props.activeRun.status)], ["Kelengkapan", completenessLabel(props.activeRun.completeness)], ["Lulus", props.activeRun.passCount], ["Peringatan", props.activeRun.warningCount], ["Masalah", props.activeRun.errorCount], ["Jumlah temuan", props.activeRun.totalFindings], ["Temuan baru", props.activeRun.newFindings], ["Temuan lama", props.activeRun.existingFindings], ["Terselesaikan", props.activeRun.resolvedFindings], ["Aturan bermasalah", props.activeRun.failedRuleCount], ["Produk", props.activeRun.productCount], ["Varian", props.activeRun.variantCount]] : [];
  return <section role="tabpanel" className="grid gap-6"><div className="border border-brand-softGray bg-white p-5 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">3. Jalankan Pemeriksaan Data</h2><p className="mt-1 text-sm text-brand-charcoal/55">Pemeriksaan hanya membaca data. Produk, status, harga, stok, dan media tidak akan diubah.</p></div><button type="button" onClick={props.onRun} disabled={props.working || props.estimate?.mode !== "DIRECT"} className="min-h-11 rounded-full bg-brand-green px-6 text-sm font-semibold text-white disabled:opacity-40">Jalankan Pemeriksaan</button></div>{props.activeRun ? <><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-6">{runSummary.map(([label, value]) => <div key={String(label)} className="border p-3"><p className="text-xs text-brand-charcoal/50">{label}</p><p className="mt-1 font-semibold">{value}</p></div>)}</div><div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={() => props.onReport("xlsx")} disabled={props.working || props.activeRun?.completeness !== "COMPLETE"} className="rounded-full border px-4 py-2 text-xs font-semibold disabled:opacity-40">Unduh Laporan XLSX</button><button type="button" onClick={() => props.onReport("csv")} disabled={props.working || props.activeRun?.completeness !== "COMPLETE"} className="rounded-full border px-4 py-2 text-xs font-semibold disabled:opacity-40">Unduh Laporan CSV</button></div></> : null}</div>
    {props.activeRun ? <div className="border border-brand-softGray bg-white p-5 sm:p-6"><h2 className="text-lg font-semibold">Temuan</h2><div className="mt-4 grid gap-3 md:grid-cols-3"><label className="text-sm font-semibold">Tingkat masalah<select value={props.findingSeverity} onChange={(event) => props.onSeverity(event.target.value)} className="mt-2 min-h-11 w-full border bg-white px-3 font-normal"><option value="all">Semua</option><option value="ERROR">Masalah</option><option value="WARNING">Peringatan</option></select></label><label className="text-sm font-semibold">Perkembangan<select value={props.findingLifecycle} onChange={(event) => props.onLifecycle(event.target.value)} className="mt-2 min-h-11 w-full border bg-white px-3 font-normal"><option value="all">Semua</option><option value="NEW">Baru</option><option value="EXISTING">Masih Ada</option><option value="RESOLVED">Terselesaikan</option><option value="NOT_EVALUATED">Belum Diperiksa</option></select></label><label className="text-sm font-semibold">Produk / SKU / masalah<input value={props.findingQuery} onChange={(event) => props.onQuery(event.target.value)} className="mt-2 min-h-11 w-full border px-3 font-normal" /></label><label className="text-sm font-semibold">Kode masalah<input value={props.findingFilters.issueCode} onChange={(event) => props.onFindingFilters({ ...props.findingFilters, issueCode: event.target.value })} className="mt-2 min-h-11 w-full border px-3 font-normal" /></label><label className="text-sm font-semibold">Kategori<select value={props.findingFilters.categoryId} onChange={(event) => props.onFindingFilters({ ...props.findingFilters, categoryId: event.target.value })} className="mt-2 min-h-11 w-full border bg-white px-3 font-normal"><option value="">Semua</option>{(props.config?.categories || []).map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label className="text-sm font-semibold">Status produk<select value={props.findingFil