"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import { createSupabaseClient } from "@/lib/supabase";
import {
  DEFAULT_SITE_MEDIA,
  parseSiteMediaDefaults,
  SITE_MEDIA_SETTING_KEY,
  type SiteMediaDefaults
} from "@/lib/site-media";

type MediaChoice = {
  id: string;
  name: string;
  public_url: string;
  folder: string;
};

type SlotDefinition = {
  key: keyof SiteMediaDefaults;
  label: string;
  description: string;
  ratio: string;
};

const slots: SlotDefinition[] = [
  { key: "heroDesktop", label: "Hero default desktop", description: "Dipakai bila slide hero belum memiliki gambar desktop.", ratio: "1920 × 900" },
  { key: "heroMobile", label: "Hero default mobile", description: "Dipakai bila slide hero belum memiliki gambar mobile.", ratio: "1080 × 1350 (4:5)" },
  { key: "product", label: "Produk default", description: "Dipakai untuk produk, kategori, atau layanan yang belum memiliki foto.", ratio: "2000 × 2500 (4:5)" },
  { key: "pageHeroDesktop", label: "Page Hero default desktop", description: "Fallback untuk hero halaman kategori dan layanan.", ratio: "1920 × 800" },
  { key: "pageHeroMobile", label: "Page Hero default mobile", description: "Fallback mobile untuk hero halaman kategori dan layanan.", ratio: "1080 × 1350 (4:5)" },
  { key: "bannerDesktop", label: "Banner default desktop", description: "Fallback banner Instagram dan campaign.", ratio: "1920 × 800" },
  { key: "bannerMobile", label: "Banner default mobile", description: "Fallback banner mobile.", ratio: "1080 × 1350 (4:5)" },
  { key: "store", label: "Store default", description: "Dipakai apabila foto store belum diatur.", ratio: "1200 × 800" },
  { key: "benefit", label: "Benefit/About default", description: "Dipakai untuk section benefit atau tentang kami yang belum memiliki foto.", ratio: "1200 × 900" },
  { key: "socialPreview", label: "Social preview default", description: "Gambar cadangan untuk preview share dan Open Graph.", ratio: "1200 × 630" }
];

export function SiteMediaSettingsAdmin() {
  const [values, setValues] = useState<SiteMediaDefaults>(DEFAULT_SITE_MEDIA);
  const [media, setMedia] = useState<MediaChoice[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [status, setStatus] = useState("");

  async function load() {
    const supabase = createSupabaseClient();
    if (!supabase) return;
    setLoading(true);

    const [settingResult, mediaResult] = await Promise.all([
      supabase
        .from("website_settings")
        .select("value")
        .eq("setting_key", SITE_MEDIA_SETTING_KEY)
        .maybeSingle(),
      supabase
        .from("media_assets")
        .select("id,name,public_url,folder")
        .eq("status_aktif", true)
        .eq("media_type", "image")
        .order("created_at", { ascending: false })
    ]);

    setLoading(false);
    if (settingResult.error) {
      setStatus("Pengaturan gambar belum dapat dimuat. Coba lagi.");
    } else {
      setValues(parseSiteMediaDefaults(settingResult.data?.value));
      setStatus("");
    }
    setMedia((mediaResult.data || []) as MediaChoice[]);
  }

  useEffect(() => {
    load();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const groupedMedia = useMemo<Array<[string, MediaChoice[]]>>(() => {
    const groups = media.reduce<Record<string, MediaChoice[]>>((currentGroups, item) => {
      const group = item.folder || "Lainnya";
      currentGroups[group] = [...(currentGroups[group] || []), item];
      return currentGroups;
    }, {});
    return Object.entries(groups).sort(([left], [right]) => left.localeCompare(right));
  }, [media]);

  async function save() {
    const supabase = createSupabaseClient();
    if (!supabase) return;
    setSaving(true);
    const { error } = await supabase.from("website_settings").upsert(
      {
        setting_key: SITE_MEDIA_SETTING_KEY,
        label: "Gambar Default Website",
        value: values,
        description: "Fallback media publik yang dapat diatur dari admin.",
        group_name: "public_media",
        updated_at: new Date().toISOString()
      },
      { onConflict: "setting_key" }
    );
    setSaving(false);
    setStatus(error ? "Gambar website belum dapat disimpan. Coba lagi." : "Gambar default website berhasil disimpan.");
  }

  if (loading) return <div className="mt-6 h-64 animate-pulse bg-white" />;

  return (
    <div className="mt-6 grid gap-5">
      <section className="border border-brand-softGray bg-white p-5 sm:p-6">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[.18em] text-brand-charcoal/45">Media global</p>
            <h2 className="mt-2 text-2xl font-semibold">Gambar Default Website</h2>
            <p className="mt-2 max-w-3xl text-sm leading-6 text-brand-charcoal/65">
              Gambar khusus konten tetap diatur pada menu Hero, Produk, Kategori, Store, Banner, dan Page Hero. Pengaturan ini menjadi cadangan agar tidak ada foto kosong atau broken image.
            </p>
          </div>
          <Link href="/admin/media" className="inline-flex min-h-11 items-center justify-center rounded-full border border-brand-softGray px-5 text-sm font-semibold hover:border-brand-charcoal">
            Buka Galeri Media
          </Link>
        </div>
        {status ? <p role="status" className="mt-4 bg-brand-offWhite p-3 text-sm font-semibold">{status}</p> : null}
      </section>

      <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {slots.map((slot) => {
          const url = values[slot.key];
          return (
            <article key={slot.key} className="border border-brand-softGray bg-white p-4">
              <div className="overflow-hidden bg-brand-offWhite">
                <img src={url} alt={`Pratinjau ${slot.label}`} className="aspect-[4/3] w-full object-cover" />
              </div>
              <h3 className="mt-4 font-semibold">{slot.label}</h3>
              <p className="mt-1 text-xs font-semibold text-brand-green">Rekomendasi {slot.ratio}</p>
              <p className="mt-2 min-h-10 text-sm leading-5 text-brand-charcoal/60">{slot.description}</p>
              <label className="mt-4 grid gap-2 text-xs font-semibold">
                Pilih dari Galeri Media
                <select
                  value={url}
                  onChange={(event) => setValues((current) => ({ ...current, [slot.key]: event.target.value }))}
                  className="min-h-11 rounded-lg border border-brand-softGray bg-white px-3 text-sm font-normal"
                >
                  <option value={DEFAULT_SITE_MEDIA[slot.key]}>Placeholder logo DEBRODER</option>
                  {groupedMedia.map(([folder, items]) => (
                    <optgroup key={folder} label={folder}>
                      {items.map((asset) => <option key={asset.id} value={asset.public_url}>{asset.name}</option>)}
                    </optgroup>
                  ))}
                </select>
              </label>
              <label className="mt-3 grid gap-2 text-xs font-semibold">
                Atau URL gambar
                <input
                  value={url}
                  onChange={(event) => setValues((current) => ({ ...current, [slot.key]: event.target.value }))}
                  className="min-h-11 rounded-lg border border-brand-softGray px-3 text-sm font-normal"
                />
              </label>
            </article>
          );
        })}
      </section>

      <div className="sticky bottom-4 flex justify-end">
        <button type="button" onClick={save} disabled={saving} className="min-h-12 rounded-full bg-brand-green px-7 text-sm font-semibold text-white shadow-lg disabled:opacity-50">
          {saving ? "Menyimpan..." : "Simpan Semua Gambar"}
        </button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { createSupabaseClient } from "@/lib/supabase";

type ProductRow = {
  id: string;
  nama: string;
};

type VariantRow = {
  id: string;
  product_id: string;
  variant_name: string | null;
  color_name: string | null;
  sku: string | null;
};

type RelationCounts = {
  sizes: number;
  images: number;
  orders: number;
  quotations: number;
};

function variantLabel(variant?: VariantRow | null) {
  return variant?.variant_name || variant?.color_name || "Varian";
}

export function VariantDeleteManager() {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [products, setProducts] = useState<ProductRow[]>([]);
  const [variants, setVariants] = useState<VariantRow[]>([]);
  const [productId, setProductId] = useState("");
  const [variantId, setVariantId] = useState("");
  const [confirmText, setConfirmText] = useState("");
  const [counts, setCounts] = useState<RelationCounts>({
    sizes: 0,
    images: 0,
    orders: 0,
    quotations: 0
  });
  const [message, setMessage] = useState<string | null>(null);

  const productVariants = useMemo(
    () => variants.filter((variant) => variant.product_id === productId),
    [variants, productId]
  );

  const selectedVariant =
    variants.find((variant) => variant.id === variantId) || null;
  const expectedText = variantLabel(selectedVariant);

  async function loadData() {
    const supabase = createSupabaseClient();

    if (!supabase) {
      setMessage("Layanan data belum tersedia. Hubungi pengelola sistem.");
      return;
    }

    setLoading(true);
    setMessage(null);

    const [productResult, variantResult] = await Promise.all([
      supabase.from("products").select("id,nama").order("nama"),
      supabase
        .from("product_variants")
        .select("id,product_id,variant_name,color_name,sku")
        .order("sort_order")
    ]);

    setLoading(false);

    if (productResult.error || variantResult.error) {
      setMessage(
        productResult.error?.message ||
          variantResult.error?.message ||
          "Gagal memuat data."
      );
      return;
    }

    const nextProducts = (productResult.data || []) as ProductRow[];
    const nextVariants = (variantResult.data || []) as VariantRow[];

    setProducts(nextProducts);
    setVariants(nextVariants);

    const nextProductId = productId || nextProducts[0]?.id || "";
    setProductId(nextProductId);

    const firstVariant = nextVariants.find(
      (variant) => variant.product_id === nextProductId
    );
    setVariantId((current) => current || firstVariant?.id || "");
  }

  async function loadCounts(targetVariantId: string) {
    const supabase = createSupabaseClient();

    if (!supabase || !targetVariantId) {
      setCounts({ sizes: 0, images: 0, orders: 0, quotations: 0 });
      return;
    }

    const [sizes, images, orders, quotations] = await Promise.all([
      supabase
        .from("product_variant_sizes")
        .select("id", { count: "exact", head: true })
        .eq("variant_id", targetVariantId),
      supabase
        .from("product_variant_images")
        .select("id", { count: "exact", head: true })
        .eq("variant_id", targetVariantId),
      supabase
        .from("order_items")
        .select("id", { count: "exact", head: true })
        .eq("variant_id", targetVariantId),
      supabase
        .from("quotation_draft_items")
        .select("id", { count: "exact", head: true })
        .eq("product_variant_id", targetVariantId)
    ]);

    setCounts({
      sizes: sizes.count || 0,
      images: images.count || 0,
      orders: orders.count || 0,
      quotations: quotations.count || 0
    });
  }

  useEffect(() => {
    if (open) {
      void loadData();
    }
  }, [open]);

  useEffect(() => {
    const firstVariant = productVariants[0];

    if (!productVariants.some((variant) => variant.id === variantId)) {
      setVariantId(firstVariant?.id || "");
    }
  }, [productId, productVariants, variantId]);

  useEffect(() => {
    setConfirmText("");
    void loadCounts(variantId);
  }, [variantId]);

  async function deleteVariant() {
    if (!selectedVariant || confirmText.trim() !== expectedText) {
      return;
    }

    const supabase = createSupabaseClient();

    if (!supabase) {
      return;
    }

    setDeleting(true);
    setMessage(null);

    const { error } = await supabase
      .from("product_variants")
      .delete()
      .eq("id", selectedVariant.id);

    setDeleting(false);

    if (error) {
      setMessage("Varian belum dapat dihapus. Periksa keterkaitan data lalu coba lagi.");
      return;
    }

    setMessage(`Varian ${expectedText} berhasil dihapus.`);
    setConfirmText("");
    setVariantId("");
    await loadData();
  }

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="fixed bottom-6 right-6 z-[110] rounded-full bg-red-700 px-5 py-3 text-sm font-semibold text-white shadow-lg"
      >
        Hapus Varian
      </button>

      {open ? (
        <div
          className="fixed inset-0 z-[130] overflow-y-auto bg-black/60 p-4 sm:p-8"
          role="dialog"
          aria-modal="true"
          aria-label="Hapus varian produk"
        >
          <div className="mx-auto max-w-xl bg-white p-5 sm:p-7">
            <div className="flex items-start justify-between gap-4">
              <div>
                <p className="text-xs font-semibold uppercase tracking-[0.16em] text-red-700">
                  Zona berbahaya
                </p>
                <h2 className="mt-2 text-2xl font-semibold">
                  Hapus varian produk
                </h2>
                <p className="mt-2 text-sm leading-6 text-black/60">
                  Ukuran dan galeri milik varian akan ikut terhapus. Riwayat
                  order dan quotation tetap tersimpan, tetapi referensi
                  variannya menjadi kosong.
                </p>
              </div>

              <button
                type="button"
                onClick={() => setOpen(false)}
                className="grid h-10 w-10 place-items-center rounded-full bg-black/5 text-xl"
              >
                ×
              </button>
            </div>

            {message ? (
              <p className="mt-5 border p-4 text-sm font-semibold">{message}</p>
            ) : null}

            <div className="mt-6 grid gap-4">
              <label className="text-sm font-semibold">
                Produk
                <select
                  value={productId}
                  onChange={(event) => setProductId(event.target.value)}
                  className="mt-2 min-h-11 w-full border px-4"
                >
                  <option value="">Pilih produk</option>
                  {products.map((product) => (
                    <option key={product.id} value={product.id}>
                      {product.nama}
                    </option>
                  ))}
                </select>
              </label>

              <label className="text-sm font-semibold">
                Varian
                <select
                  value={variantId}
                  onChange={(event) => setVariantId(event.target.value)}
                  className="mt-2 min-h-11 w-full border px-4"
                >
                  <option value="">Pilih varian</option>
                  {productVariants.map((variant) => (
                    <option key={variant.id} value={variant.id}>
                      {variantLabel(variant)}
                      {variant.sku ? ` — ${variant.sku}` : ""}
                    </option>
                  ))}
                </select>
              </label>

              {selectedVariant ? (
                <div className="grid grid-cols-2 gap-3 bg-black/[0.03] p-4 text-sm sm:grid-cols-4">
                  <div>
                    <span className="block text-xs text-black/50">Ukuran</span>
                    <strong>{counts.sizes}</strong>
                  </div>
                  <div>
                    <span className="block text-xs text-black/50">Foto</span>
                    <strong>{counts.images}</strong>
                  </div>
                  <div>
                    <span className="block text-xs text-black/50">
                      Order terkait
                    </span>
                    <strong>{counts.orders}</strong>
                  </div>
                  <div>
                    <span className="block text-xs text-black/50">
                      Penawaran terkait
                    </span>
                    <strong>{counts.quotations}</strong>
                  </div>
                </div>
              ) : null}

              <label className="text-sm font-semibold">
                Ketik nama varian untuk konfirmasi:{" "}
                <span className="text-red-700">
                  {expectedText || "—"}
                </span>
                <input
                  value={confirmText}
                  onChange={(event) => setConfirmText(event.target.value)}
                  className="mt-2 min-h-11 w-full border px-4"
                  placeholder={expectedText || "Pilih varian dahulu"}
                />
              </label>

              <button
                type="button"
                disabled={
                  loading ||
                  deleting ||
                  !selectedVariant ||
                  confirmText.trim() !== expectedText
                }
                onClick={() => void deleteVariant()}
                className="min-h-12 rounded-full bg-red-700 px-6 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-40"
              >
                {deleting ? "Menghapus..." : "Hapus varian permanen"}
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import type { CartItem, RevalidationResult } from "@/lib/types";
import {
  clearCart,
  readCart,
  removeCartItem,
  setCartItemQuantity
} from "@/lib/cart/storage";
import {
  getCartEstimatedTotal,
  getCartQuantity,
  getCartServiceSubtotal,
  getCartSubtotal
} from "@/lib/cart/operations";
import { formatRupiah } from "@/lib/money";
import { buildWhatsAppUrl } from "@/lib/whatsapp";

export function CartPanel() {
  const [items, setItems] = useState<CartItem[]>([]);
  const [warnings, setWarnings] = useState<string[]>([]);

  useEffect(() => {
    function syncCart() {
      setItems(readCart().items);
    }

    syncCart();
    window.addEventListener("debroder-cart-updated", syncCart);
    return () => window.removeEventListener("debroder-cart-updated", syncCart);
  }, []);

  useEffect(() => {
    if (items.length === 0) {
      return;
    }

    let isActive = true;

    async function revalidate() {
      const response = await fetch("/api/cart/revalidate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          items: items.map((item) => ({
            product_variant_size_id: item.product_variant_size_id,
            product_id: item.product_id,
            quantity: item.quantity,
            unit_price: item.unit_price,
            price_tier_id: item.price_tier?.tier_id ?? null
          }))
        })
      });

      if (!response.ok || !isActive) {
        return;
      }

      const payload = (await response.json()) as { items?: RevalidationResult[] };
      const nextWarnings =
        payload.items
          ?.filter((item) => item.status !== "ok")
          .map((item) => item.message ?? "Data produk berubah.") ?? [];

      setWarnings(nextWarnings);
    }

    void revalidate();
    return () => {
      isActive = false;
    };
  }, [items]);

  const subtotal = useMemo(() => getCartSubtotal(items), [items]);
  const serviceSubtotal = useMemo(() => getCartServiceSubtotal(items), [items]);
  const estimatedTotal = useMemo(() => getCartEstimatedTotal(items), [items]);
  const totalQuantity = useMemo(() => getCartQuantity(items), [items]);

  function updateQuantity(productVariantSizeId: string, quantity: number) {
    const nextWarnings = setCartItemQuantity(productVariantSizeId, quantity);
    setWarnings(nextWarnings);
    setItems(readCart().items);
  }

  function removeItem(productVariantSizeId: string) {
    removeCartItem(productVariantSizeId);
    setItems(readCart().items);
  }

  function emptyCart() {
    clearCart();
    setItems([]);
    setWarnings([]);
  }

  if (items.length === 0) {
    return (
      <div className="notice">
        Keranjang kosong. Pilih produk dari katalog untuk mulai membuat pesanan.
      </div>
    );
  }

  return (
    <div className="cart-layout">
      <section className="cart-list" aria-label="Isi keranjang">
        {warnings.length > 0 ? (
          <div className="notice warning">
            {warnings.map((warning) => (
              <p key={warning}>{warning}</p>
            ))}
          </div>
        ) : null}

        {items.map((item) => (
          <article className="cart-line" key={item.product_variant_size_id}>
            {item.thumbnail ? (
              <img src={item.thumbnail} alt={`${item.nama_produk} ${item.warna}`} />
            ) : (
              <div />
            )}
            <div className="cart-meta">
              <strong>{item.nama_produk}</strong>
              <span className="muted">
                {item.warna} / {item.ukuran} - {item.sku}
              </span>
              <span>{formatRupiah(item.unit_price)} / pcs</span>
              {item.services && item.services.length > 0 ? (
                <span className="muted">
                  {item.services
                    .map((service) => service.service_name)
                    .join(", ")}
                </span>
              ) : null}
            </div>
            <div className="control-row">
              <input
                className="quantity-input"
                min={1}
                max={item.stock_snapshot}
                onChange={(event) =>
                  updateQuantity(
                    item.product_variant_size_id,
                    Number(event.target.value)
                  )
                }
                type="number"
                value={item.quantity}
              />
              <button
                className="danger-button"
                onClick={() => removeItem(item.product_variant_size_id)}
                type="button"
              >
                Hapus
              </button>
            </div>
          </article>
        ))}
      </section>

      <aside className="summary-box">
        <h2 className="section-title">Ringkasan</h2>
        <div className="control-row" style={{ justifyContent: "space-between" }}>
          <span>Total item</span>
          <strong>{totalQuantity} pcs</strong>
        </div>
        <div className="control-row" style={{ justifyContent: "space-between" }}>
          <span>Subtotal</span>
          <strong>{formatRupiah(subtotal)}</strong>
        </div>
        <div className="control-row" style={{ justifyContent: "space-between" }}>
          <span>Custom</span>
          <strong>{formatRupiah(serviceSubtotal)}</strong>
        </div>
        <div className="control-row" style={{ justifyContent: "space-between" }}>
          <span>Total estimasi</span>
          <strong>{formatRupiah(estimatedTotal)}</strong>
        </div>
        <a
          className="primary-button"
          href={buildWhatsAppUrl(items)}
          rel="noreferrer"
          target="_blank"
        >
          Kirim WhatsApp
        </a>
        <button className="secondary-button" onClick={emptyCart} type="button">
          Kosongkan
        </button>
      </aside>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useCart } from "@/components/CartProvider";
import { SafeImage } from "@/components/SafeImage";
import { readCustomDraft, removeCustomDraft, writeCustomDraft } from "@/lib/custom-commerce/draft-storage";
import type {
  CustomCategoryCatalog,
  CustomDesignPackage,
  CustomDesignService,
  CustomPreset,
  CustomProject,
  CustomProjectItem,
  CustomProjectPricing,
  CustomProjectSnapshot,
  CustomVariantAllocation
} from "@/lib/custom-commerce/types";
import type { PimProduct, PimProductVariant, PimProductVariantSize } from "@/lib/types";
import { fallbackImages } from "@/lib/fallback-data";
import { formatRupiah } from "@/lib/url";
import {
  changeCustomDesignPairPlacement,
  compatibleCustomPlacements,
  compatibleCustomPrintSizes,
  isCompleteCustomDesignPair,
  isCustomDesignPairCompatible,
  removeCustomDesignPackageFromItem,
  removeCustomDesignPairFromItem
} from "@/lib/custom-commerce/design-pairs";
import { parseCustomProject } from "@/lib/custom-commerce/validation";
import {
  customBuilderHydrationKey,
  shouldReplaceCustomPricing,
  shouldReplaceCustomProject,
  shouldRunCustomBuilderHydration
} from "@/lib/custom-commerce/builder-runtime";

type BuilderProps = {
  catalogs: CustomCategoryCatalog[];
  initialCategoryId: string;
  preselectedProductId?: string | null;
  requestedDraftId?: string | null;
};

const steps = ["Produk", "Varian & Jumlah", "Desain & Layanan", "Alokasi", "Ringkasan"];

export function CustomProjectBuilder({ catalogs, initialCategoryId, preselectedProductId, requestedDraftId }: BuilderProps) {
  const cart = useCart();
  const initialCatalog = catalogs.find((catalog) => catalog.category.id === initialCategoryId) ?? catalogs[0];
  const [project, setProject] = useState<CustomProject>(() => createProject(initialCatalog));
  const [step, setStep] = useState(0);
  const [hydrated, setHydrated] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [pricing, setPricing] = useState<CustomProjectPricing | null>(null);
  const [pricingState, setPricingState] = useState<"idle" | "loading" | "error">("idle");
  const [addingToCart, setAddingToCart] = useState(false);
  const [message, setMessage] = useState("");
  const [addProductValue, setAddProductValue] = useState("");
  const pricingRequestVersion = useRef(0);
  const projectRef = useRef(project);
  const pricingRef = useRef(pricing);
  const catalogsRef = useRef(catalogs);
  const initialCatalogRef = useRef(initialCatalog);
  const hydratedKeyRef = useRef<string | null>(null);
  const hydrationKey = customBuilderHydrationKey({
    catalogs,
    initialCategoryId,
    preselectedProductId,
    requestedDraftId
  });

  projectRef.current = project;
  pricingRef.current = pricing;
  catalogsRef.current = catalogs;
  initialCatalogRef.current = initialCatalog;

  useEffect(() => {
    if (!shouldRunCustomBuilderHydration(hydratedKeyRef.current, hydrationKey)) return;
    hydratedKeyRef.current = hydrationKey;

    const currentCatalogs = catalogsRef.current;
    const fallbackCatalog = initialCatalogRef.current;
    const restored = readCustomDraft(requestedDraftId);
    let nextProject: CustomProject | null = null;
    let restoredDraft = false;

    if (restored && restored.items.every((item) => currentCatalogs.some((catalog) => catalog.category.id === item.categoryId))) {
      nextProject = restored;
      restoredDraft = true;
    } else if (preselectedProductId) {
      const catalog = currentCatalogs.find((candidate) => candidate.products.some((product) => product.id === preselectedProductId)) ?? fallbackCatalog;
      const product = catalog?.products.find((candidate) => candidate.id === preselectedProductId);
      if (catalog && product) nextProject = addProductGroup(projectRef.current, catalog, product);
    }

    if (nextProject && shouldReplaceCustomProject(projectRef.current, nextProject)) {
      pricingRequestVersion.current += 1;
      projectRef.current = nextProject;
      setProject(nextProject);
    }
    if (restoredDraft) setMessage("Draft custom dipulihkan.");
    setHydrated(true);
  }, [hydrationKey, preselectedProductId, requestedDraftId]);

  useEffect(() => {
    if (!hydrated) return;
    const timer = window.setTimeout(() => writeCustomDraft(project), 350);
    return () => window.clearTimeout(timer);
  }, [hydrated, project]);

  useEffect(() => {
    if (!dirty) return;
    const warn = (event: BeforeUnloadEvent) => event.preventDefault();
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [dirty]);

  const totalQuantity = project.items.reduce((sum, item) => sum + item.allocations.reduce((itemSum, allocation) => itemSum + allocation.quantity, 0), 0);
  const selectedCatalog = catalogs.find((catalog) => catalog.category.id === project.categoryId) ?? initialCatalog;

  function mutate(updater: (current: CustomProject) => CustomProject) {
    const current = projectRef.current;
    const candidate = updater(current);
    if (!shouldReplaceCustomProject(current, candidate)) return;

    const next = { ...candidate, updatedAt: new Date().toISOString() };
    pricingRequestVersion.current += 1;
    projectRef.current = next;
    setProject(next);
    setDirty(true);
    if (pricingRef.current) {
      pricingRef.current = null;
      setPricing(null);
    }
    setPricingState("idle");
    setAddingToCart(false);
    setMessage("");
  }

  function goToStep(target: number) {
    if (target <= step) {
      setStep(target);
      setMessage("");
      return;
    }
    for (let index = 0; index < target; index += 1) {
      const issue = validateBuilderStep(project, catalogs, index);
      if (issue) {
        setStep(index);
        setPricingState("error");
        setMessage(issue);
        return;
      }
    }
    setPricingState("idle");
    setMessage("");
    setStep(target);
  }

  function choosePreset(preset: CustomPreset) {
    if (!selectedCatalog) return;
    const product = selectedCatalog.products.find((candidate) => candidate.id === preset.defaultProductId) ?? selectedCatalog.products[0];
    if (!product) return;
    const next = createProject(selectedCatalog, "preset", preset.id);
    const item = createProjectItem(selectedCatalog, product, preset);
    const presetProject = { ...next, items: [item], updatedAt: new Date().toISOString() };
    pricingRequestVersion.current += 1;
    projectRef.current = presetProject;
    setProject(presetProject);
    setDirty(true);
    if (pricingRef.current) {
      pricingRef.current = null;
      setPricing(null);
    }
    setStep(1);
  }

  function startFree() {
    mutate((current) => ({ ...current, mode: "free", presetId: null }));
    setStep(0);
  }

  function addSelectedProduct() {
    const [categoryId, productId] = addProductValue.split(":");
    const catalog = catalogs.find((candidate) => candidate.category.id === categoryId);
    const product = catalog?.products.find((candidate) => candidate.id === productId);
    if (!catalog || !product) return;
    mutate((current) => addProductGroup(current, catalog, product));
    setAddProductValue("");
  }

  async function reprice() {
    if (pricingState === "loading" || addingToCart) return;
    for (let index = 0; index < steps.length - 1; index += 1) {
      const issue = validateBuilderStep(project, catalogs, index);
      if (issue) {
        setStep(index);
        setPricingState("error");
        setMessage(issue);
        return;
      }
    }
    const requestVersion = pricingRequestVersion.current + 1;
    pricingRequestVersion.current = requestVersion;
    const requestProject = project;
    if (pricingRef.current) {
      pricingRef.current = null;
      setPricing(null);
    }
    setAddingToCart(false);
    setPricingState("loading");
    setMessage("");
    try {
      const response = await fetch("/api/custom/reprice", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ project: requestProject }) });
      const payload = await response.json() as { pricing?: CustomProjectPricing; error?: string };
      if (!response.ok || !payload.pricing) throw new Error("Harga belum dapat divalidasi. Periksa pilihan produk lalu coba lagi.");
      if (requestVersion !== pricingRequestVersion.current) return;
      if (shouldReplaceCustomPricing(pricingRef.current, payload.pricing)) {
        pricingRef.current = payload.pricing;
        setPricing(payload.pricing);
      }
      setPricingState("idle");
      setMessage(payload.pricing.status === "quotation_required" ? "Konfigurasi valid. Order akan dibuat tanpa nominal, lalu admin mengirim penawaran resmi." : "Harga pasti dan konfigurasi sudah divalidasi server.");
      setDirty(false);
    } catch (error) {
      if (requestVersion !== pricingRequestVersion.current) return;
      setPricingState("error");
      setMessage("Harga belum dapat divalidasi. Periksa pilihan produk lalu coba lagi.");
    }
  }

  function addToCart() {
    if (addingToCart || pricingState === "loading" || !pricing || pricing.issues.length) return;
    const canonicalProject = parseCustomProject(project);
    if (!canonicalProject) {
      setPricingState("error");
      setMessage("Pilih minimal satu Posisi Desain dan Size Desain.");
      return;
    }
    setAddingToCart(true);
    const snapshot: CustomProjectSnapshot = { ...canonicalProject, pricing };
    cart.addCustomProject(snapshot);
    writeCustomDraft(project);
    setDirty(false);
    setMessage("Custom Project masuk ke keranjang.");
    cart.openCart();
  }

  async function discardDraft() {
    pricingRequestVersion.current += 1;
    await deleteUploadRefs(project.items.flatMap((item) => item.uploads), project.sessionToken);
    removeCustomDraft(project.id);
    const emptyProject = createProject(initialCatalogRef.current);
    projectRef.current = emptyProject;
    setProject(emptyProject);
    if (pricingRef.current) {
      pricingRef.current = null;
      setPricing(null);
    }
    setAddingToCart(false);
    setDirty(false);
    setStep(0);
    setMessage("Draft dihapus.");
  }

  if (!initialCatalog) return null;
  const activeCatalog = selectedCatalog ?? initialCatalog;

  return (
    <section className="section-shell pb-20">
      <div className="rounded-[30px] bg-white p-4 sm:p-6 lg:p-8">
        <div className="flex flex-wrap items-start justify-between gap-5">
          <div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-black/45">Custom Project</p><h2 className="mt-2 text-3xl font-semibold tracking-tight">Rakit pesananmu</h2><p className="mt-2 max-w-2xl text-sm leading-7 text-black/60">Satu proyek dapat memuat banyak produk, ukuran, paket desain, layanan, dan personalisasi.</p></div>
          <button type="button" onClick={() => void discardDraft()} className="text-sm font-semibold text-red-700 underline underline-offset-4">Hapus draft</button>
        </div>

        <div className="mt-7 grid gap-3 sm:grid-cols-2">
          <ModeButton active={project.mode === "preset"} title="Paket Instan" detail="Mulai dari preset CMS lalu edit sesuai kebutuhan." onClick={() => activeCatalog.presets[0] ? choosePreset(activeCatalog.presets[0]) : undefined} disabled={!activeCatalog.category.supportsQuickCustom || !activeCatalog.presets.length} />
          <ModeButton active={project.mode === "free"} title="Custom Bebas" detail="Bangun proyek dari produk PIM aktif." onClick={startFree} disabled={!activeCatalog.category.supportsFullCustom} />
        </div>

        {activeCatalog.category.supportsQuickCustom && activeCatalog.presets.length ? (
          <div className="mt-7"><h3 className="text-lg font-semibold">Paket Instan</h3><div className="mt-3 flex snap-x gap-3 overflow-x-auto pb-2">
            {activeCatalog.presets.map((preset) => <PresetCard key={preset.id} preset={preset} selected={project.presetId === preset.id} onClick={() => choosePreset(preset)} />)}
          </div></div>
        ) : null}

        <ol className="mt-8 grid grid-cols-2 gap-2 sm:grid-cols-5" aria-label="Tahapan Custom Project">
          {steps.map((label, index) => <li key={label}><button type="button" onClick={() => goToStep(index)} aria-current={step === index ? "step" : undefined} className={`min-h-11 w-full rounded-full px-3 text-xs font-semibold ${step === index ? "bg-black text-white" : "bg-[#f5f5ef] text-black/60"}`}>{index + 1}. {label}</button></li>)}
        </ol>

        <div className="mt-8">
          {step === 0 ? <ProductsStep catalogs={catalogs} project={project} addProductValue={addProductValue} setAddProductValue={setAddProductValue} addSelectedProduct={addSelectedProduct} mutate={mutate} /> : null}
          {step === 1 ? <AllocationsStep catalogs={catalogs} project={project} mutate={mutate} /> : null}
          {step === 2 ? <DesignStep catalogs={catalogs} project={project} mutate={mutate} /> : null}
          {step === 3 ? <AssignmentStep catalogs={catalogs} project={project} mutate={mutate} /> : null}
          {step === 4 ? <ReviewStep catalogs={catalogs} project={project} pricing={pricing} totalQuantity={totalQuantity} pricingState={pricingState} addingToCart={addingToCart} onReprice={reprice} onAddToCart={addToCart} /> : null}
        </div>

        {message ? <p role="status" className={`mt-6 rounded-2xl p-4 text-sm ${pricingState === "error" ? "bg-red-50 text-red-800" : "bg-[#e9f4ee] text-[#063d24]"}`}>{message}</p> : null}
        <div className="mt-8 flex items-center justify-between gap-4 border-t border-black/10 pt-6">
          <button type="button" disabled={step === 0} onClick={() => goToStep(Math.max(0, step - 1))} className="min-h-11 rounded-full border border-black/15 px-5 text-sm font-semibold disabled:opacity-35">Kembali</button>
          <button type="button" disabled={step === steps.length - 1} onClick={() => goToStep(Math.min(steps.length - 1, step + 1))} className="min-h-11 rounded-full bg-black px-5 text-sm font-semibold text-white disabled:opacity-35">Lanjut</button>
        </div>
      </div>
    </section>
  );
}

function ProductsStep({ catalogs, project, addProductValue, setAddProductValue, addSelectedProduct, mutate }: {
  catalogs: CustomCategoryCatalog[];
  project: CustomProject;
  addProductValue: string;
  setAddProductValue: (value: string) => void;
  addSelectedProduct: () => void;
  mutate: (updater: (project: CustomProject) => CustomProject) => void;
}) {
  return <div><StepHeading title="Produk" detail="Tambahkan satu atau beberapa produk custom. Konfigurasi yang sudah ada tidak akan hilang." />
    <div className="mt-5 grid gap-4 lg:grid-cols-2">{project.items.map((item) => {
      const catalog = catalogs.find((candidate) => candidate.category.id === item.categoryId);
      const product = catalog?.products.find((candidate) => candidate.id === item.productId);
      return <article key={item.id} className="flex gap-4 rounded-[24px] bg-[#f5f5ef] p-4">
        <div className="relative h-28 w-24 shrink-0 overflow-hidden rounded-2xl bg-white"><SafeImage src={productImage(product)} fallbackSrc={fallbackImages.product} alt={item.productName} fill className="object-cover" sizes="96px" /></div>
        <div className="min-w-0 flex-1"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-black/45">{item.categoryName}</p><h3 className="mt-1 font-semibold">{item.productName}</h3><p className="mt-2 text-xs text-black/55">{item.allocations.reduce((sum, allocation) => sum + allocation.quantity, 0)} pcs · {item.leadTime}</p>
          <button type="button" disabled={project.items.length === 1} onClick={() => void deleteUploadRefs(item.uploads, project.sessionToken).finally(() => mutate((current) => ({ ...current, items: current.items.filter((candidate) => candidate.id !== item.id) })))} className="mt-3 text-xs font-semibold text-red-700 underline disabled:opacity-30">Hapus Product Group</button>
        </div>
      </article>;
    })}</div>
    <div className="mt-6 grid gap-3 rounded-[24px] border border-dashed border-black/20 p-4 sm:grid-cols-[1fr_auto]">
      <label className="grid gap-2 text-sm font-semibold">Tambah Produk Custom<select value={addProductValue} onChange={(event) => setAddProductValue(event.target.value)} className="min-h-11 rounded-xl border border-black/15 bg-white px-3 font-normal"><option value="">Pilih produk</option>{catalogs.flatMap((catalog) => catalog.products.map((product) => <option key={`${catalog.category.id}:${product.id}`} value={`${catalog.category.id}:${product.id}`}>{catalog.category.name} · {product.name}</option>))}</select></label>
      <button type="button" disabled={!addProductValue} onClick={addSelectedProduct} className="min-h-11 self-end rounded-full bg-black px-5 text-sm font-semibold text-white disabled:opacity-35">+ Tambah Produk</button>
    </div>
  </div>;
}

function AllocationsStep({ catalogs, project, mutate }: { catalogs: CustomCategoryCatalog[]; project: CustomProject; mutate: (updater: (project: CustomProject) => CustomProject) => void }) {
  return <div><StepHeading title="Varian & Jumlah" detail="Setiap baris adalah kombinasi warna/ukuran aktual. Harga ukuran dan varian dihitung terpisah." />
    <div className="mt-5 grid gap-6">{project.items.map((item) => {
      const catalog = catalogs.find((candidate) => candidate.category.id === item.categoryId);
      const product = catalog?.products.find((candidate) => candidate.id === item.productId);
      if (!product) return null;
      const options = variantSizeOptions(product);
      return <section key={item.id} className="rounded-[24px] bg-[#f5f5ef] p-4 sm:p-5"><div className="flex items-center justify-between gap-4"><h3 className="font-semibold">{item.productName}</h3><span className="text-sm font-semibold">{item.allocations.reduce((sum, allocation) => sum + allocation.quantity, 0)} pcs</span></div>
        <div className="mt-4 grid gap-3">{item.allocations.map((allocation) => <div key={allocation.id} className="grid gap-3 rounded-2xl bg-white p-3 sm:grid-cols-[1fr_120px_auto]">
          <label className="grid gap-1 text-xs font-semibold text-black/55">Varian / ukuran<select value={allocation.variantSizeId} onChange={(event) => mutate((current) => updateProjectItem(current, item.id, (target) => ({ ...target, allocations: target.allocations.map((candidate) => candidate.id === allocation.id ? allocationFromOption(options.find((option) => option.variantSize.id === event.target.value)!, candidate.quantity, candidate.id, candidate.designPackageId) : candidate) })))} className="min-h-11 rounded-xl border border-black/15 px-3 text-sm font-normal text-black">{options.map((option) => <option key={option.variantSize.id} value={option.variantSize.id}>{option.variant.name} · {option.variantSize.size.name} · {option.variantSize.sku}</option>)}</select></label>
          <label className="grid gap-1 text-xs font-semibold text-black/55">Jumlah<input type="number" min={1} max={1000} value={allocation.quantity} onChange={(event) => mutate((current) => updateProjectItem(current, item.id, (target) => ({ ...target, allocations: target.allocations.map((candidate) => candidate.id === allocation.id ? { ...candidate, quantity: clampQuantity(event.target.value) } : candidate) })))} className="min-h-11 rounded-xl border border-black/15 px-3 text-sm text-black" /></label>
          <button type="button" disabled={item.allocations.length === 1} onClick={() => mutate((current) => updateProjectItem(current, item.id, (target) => ({ ...target, allocations: target.allocations.filter((candidate) => candidate.id !== allocation.id) })))} className="self-end pb-3 text-xs font-semibold text-red-700 underline disabled:opacity-30">Hapus</button>
        </div>)}</div>
        <button type="button" onClick={() => mutate((current) => updateProjectItem(current, item.id, (target) => ({ ...target, allocations: [...target.allocations, allocationFromOption(options[0], 1)] })))} className="mt-4 min-h-10 rounded-full border border-black/15 px-4 text-xs font-semibold">+ Tambah kombinasi</button>
      </section>;
    })}</div>
  </div>;
}

function DesignStep({ catalogs, project, mutate }: { catalogs: CustomCategoryCatalog[]; project: CustomProject; mutate: (updater: (project: CustomProject) => CustomProject) => void }) {
  return <div><StepHeading title="Desain & Layanan" detail="Satu Paket Desain dapat memuat beberapa layanan. Paket dapat diduplikasi lalu dialokasikan ke kombinasi berbeda." />
    <div className="mt-5 grid gap-7">{project.items.map((item) => {
      const catalog = catalogs.find((candidate) => candidate.category.id === item.categoryId);
      if (!catalog) return null;
      return <section key={item.id}><div className="flex flex-wrap items-center justify-between gap-3"><h3 className="text-lg font-semibold">{item.productName}</h3><button type="button" onClick={() => mutate((current) => updateProjectItem(current, item.id, (target) => ({ ...target, designPackages: [...target.designPackages, createDesignPackage(target.designPackages.length + 1)] })))} className="min-h-10 rounded-full bg-black px-4 text-xs font-semibold text-white">+ Paket Desain</button></div>
        <div className="mt-4 grid gap-4">{item.designPackages.map((designPackage) => <DesignPackageEditor key={designPackage.id} catalog={catalog} item={item} designPackage={designPackage} sessionToken={project.sessionToken} mutate={mutate} />)}</div>
      </section>;
    })}</div>
  </div>;
}

function DesignPackageEditor({ catalog, item, designPackage, sessionToken, mutate }: { catalog: CustomCategoryCatalog; item: CustomProjectItem; designPackage: CustomDesignPackage; sessionToken: string; mutate: (updater: (project: CustomProject) => CustomProject) => void }) {
  const [serviceId, setServiceId] = useState("");
  const compatibleServices = catalog.services.filter((service) => catalog.compatibility.some((rule) =>
    rule.serviceId === service.id
    && (!rule.productId || rule.productId === item.productId)
    && (!rule.categoryId || rule.categoryId === item.categoryId)
  ));

  function updatePackage(update: (current: CustomDesignPackage) => CustomDesignPackage) {
    mutate((project) => updateProjectItem(project, item.id, (target) => ({
      ...target,
      designPackages: target.designPackages.map((candidate) =>
        candidate.id === designPackage.id ? update(candidate) : candidate
      )
    })));
  }

  function addService() {
    if (!serviceId) return;
    mutate((project) => updateProjectItem(project, item.id, (target) => {
      const autoAssign = target.designPackages.length === 1;
      return {
        ...target,
        designPackages: target.designPackages.map((candidate) => candidate.id === designPackage.id
          ? { ...candidate, services: [...candidate.services, createDesignService(serviceId)] }
          : candidate),
        allocations: autoAssign
          ? target.allocations.map((allocation) => allocation.designPackageId === null
            ? { ...allocation, designPackageId: designPackage.id }
            : allocation)
          : target.allocations
      };
    }));
    setServiceId("");
  }

  function duplicate() {
    mutate((project) => updateProjectItem(project, item.id, (target) => ({
      ...target,
      designPackages: [...target.designPackages, {
        ...designPackage,
        id: localId(),
        name: `${designPackage.name} (salinan)`,
        services: designPackage.services.map((service) => ({
          ...service,
          id: localId(),
          placementId: null,
          printSizeId: null,
          uploadIds: []
        }))
      }]
    })));
  }

  function removeSelection(selectionId: string) {
    mutate((project) => updateProjectItem(project, item.id, (target) =>
      removeCustomDesignPairFromItem(target, designPackage.id, selectionId)
    ));
  }

  const assignedQuantity = item.allocations
    .filter((allocation) => allocation.designPackageId === designPackage.id)
    .reduce((sum, allocation) => sum + allocation.quantity, 0);

  return <article className="rounded-[24px] bg-[#f5f5ef] p-4 sm:p-5">
    <div className="flex flex-wrap items-center justify-between gap-3">
      <input aria-label="Nama Paket Desain" value={designPackage.name} maxLength={120} onChange={(event) => updatePackage((current) => ({ ...current, name: event.target.value }))} className="min-h-10 rounded-xl border border-black/15 bg-white px-3 font-semibold" />
      <div className="flex gap-3">
        <button type="button" onClick={duplicate} className="text-xs font-semibold underline">Duplikasi</button>
        <button type="button" disabled={item.designPackages.length === 1} onClick={() => mutate((project) => updateProjectItem(project, item.id, (target) => removeCustomDesignPackageFromItem(target, designPackage.id)))} className="text-xs font-semibold text-red-700 underline disabled:opacity-30">Hapus</button>
      </div>
    </div>
    <div className="mt-4 grid gap-3">
      {designPackage.services.map((selection) => <ServiceEditor key={selection.id} catalog={catalog} item={item} selection={selection} sessionToken={sessionToken} attachUpload={(upload) => mutate((project) => updateProjectItem(project, item.id, (target) => target.uploads.some((candidate) => candidate.id === upload.id) ? target : { ...target, uploads: [...target.uploads, upload] }))} onRemove={() => removeSelection(selection.id)} updatePackage={updatePackage} />)}
    </div>
    {designPackage.services.length ? <p className={`mt-3 text-xs font-semibold ${assignedQuantity ? "text-[#063d24]" : "text-red-700"}`}>{assignedQuantity ? `Pasangan desain paket ini dialokasikan ke ${assignedQuantity} pcs.` : "Pasangan desain sudah dipilih, tetapi paket belum dialokasikan. Selesaikan pada tahap Alokasi."}</p> : null}
    <div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto]">
      <select aria-label="Metode produksi" value={serviceId} onChange={(event) => setServiceId(event.target.value)} className="min-h-11 rounded-xl border border-black/15 bg-white px-3 text-sm">
        <option value="">Pilih metode untuk pasangan baru</option>
        {compatibleServices.map((service) => <option key={service.id} value={service.id}>{service.name}</option>)}
      </select>
      <button type="button" disabled={!serviceId} onClick={addService} className="min-h-11 rounded-full border border-black/15 px-4 text-xs font-semibold disabled:opacity-35">+ Posisi Desain</button>
    </div>
  </article>;
}

function ServiceEditor({ catalog, item, selection, sessionToken, attachUpload, onRemove, updatePackage }: { catalog: CustomCategoryCatalog; item: CustomProjectItem; selection: CustomDesignService; sessionToken: string; attachUpload: (upload: CustomProjectItem["uploads"][number]) => void; onRemove: () => void; updatePackage: (update: (current: CustomDesignPackage) => CustomDesignPackage) => void }) {
  const service = catalog.services.find((candidate) => candidate.id === selection.serviceId);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  if (!service) return null;

  const otherPlacementIds = new Set(item.designPackages.flatMap((designPackage) =>
    designPackage.services
      .filter((candidate) => candidate.id !== selection.id)
      .map((candidate) => candidate.placementId)
      .filter((placementId): placementId is string => Boolean(placementId))
  ));
  const placements = compatibleCustomPlacements(
    catalog,
    service.id,
    item.productId,
    item.categoryId
  ).filter((placement) => !otherPlacementIds.has(placement.id) || placement.id === selection.placementId);
  const printSizes = compatibleCustomPrintSizes(
    catalog,
    service.id,
    item.productId,
    item.categoryId,
    selection.placementId
  );
  const selectedPlacement = catalog.placements.find((placement) => placement.id === selection.placementId);
  const selectedPrintSize = catalog.printSizes.find((printSize) => printSize.id === selection.printSizeId);
  const duplicatePosition = Boolean(selection.placementId && otherPlacementIds.has(selection.placementId));
  const incompatiblePair = isCompleteCustomDesignPair(selection) && !isCustomDesignPairCompatible(
    catalog,
    service.id,
    item.productId,
    item.categoryId,
    selection.placementId,
    selection.printSizeId
  );
  const pairError = duplicatePosition
    ? `Posisi Desain ${selectedPlacement?.name ?? "terpilih"} sudah digunakan pada produk ini.`
    : selection.placementId && !selection.printSizeId
      ? `Pilih Size Desain untuk posisi ${selectedPlacement?.name ?? "terpilih"}.`
      : !selection.placementId && selection.printSizeId
        ? `Pilih Posisi Desain untuk Size Desain ${selectedPrintSize?.name ?? "terpilih"}.`
        : incompatiblePair
          ? `Size Desain ${selectedPrintSize?.name ?? "terpilih"} tidak kompatibel dengan posisi ${selectedPlacement?.name ?? "terpilih"}.`
          : "";
  const errorId = `design-pair-error-${selection.id}`;

  function update(updates: Partial<CustomDesignService>) {
    updatePackage((current) => ({
      ...current,
      services: current.services.map((candidate) =>
        candidate.id === selection.id ? { ...candidate, ...updates } : candidate
      )
    }));
  }

  function changePlacement(nextPlacementId: string | null) {
    const nextSelection = changeCustomDesignPairPlacement(
      selection,
      nextPlacementId,
      catalog,
      item.productId,
      item.categoryId
    );
    update({
      placementId: nextSelection.placementId,
      printSizeId: nextSelection.printSizeId
    });
  }

  async function upload(file: File | undefined) {
    if (!file) return;
    setUploading(true);
    setUploadError("");
    try {
      const form = new FormData();
      form.set("file", file);
      form.set("session_token", sessionToken);
      const response = await fetch("/api/customer-uploads", { method: "POST", body: form });
      const payload = await response.json() as { upload?: CustomProjectItem["uploads"][number]; error?: string };
      if (!response.ok || !payload.upload) {
        throw new Error("File belum dapat diunggah. Periksa jenis dan ukuran file lalu coba lagi.");
      }
      updatePackage((current) => ({
        ...current,
        services: current.services.map((candidate) => candidate.id === selection.id
          ? { ...candidate, uploadIds: [...candidate.uploadIds, payload.upload!.id] }
          : candidate)
      }));
      attachUpload(payload.upload);
    } catch (error) {
      setUploadError(error instanceof Error ? error.message : "File belum dapat diunggah. Coba lagi.");
    } finally {
      setUploading(false);
    }
  }

  return <div className="rounded-2xl bg-white p-4">
    <div className="flex items-start justify-between gap-4">
      <div>
        <p className="font-semibold">{service.name}</p>
        <p className="mt-1 text-xs font-semibold text-black/45">Posisi Desain + Size Desain</p>
        {service.description ? <p className="mt-1 text-xs leading-5 text-black/55">{service.description}</p> : null}
      </div>
      <button type="button" onClick={onRemove} className="text-xs font-semibold text-red-700 underline">Hapus pasangan</button>
    </div>
    <div className="mt-4 grid gap-3 sm:grid-cols-2">
      <Field label="Posisi Desain">
        <select value={selection.placementId ?? ""} aria-invalid={Boolean(pairError)} aria-describedby={pairError ? errorId : undefined} onChange={(event) => changePlacement(event.target.value || null)}>
          <option value="">Pilih Posisi Desain</option>
          {placements.map((placement) => <option key={placement.id} value={placement.id}>{placement.name}</option>)}
        </select>
      </Field>
      <Field label="Size Desain">
        <select disabled={!selection.placementId} value={selection.printSizeId ?? ""} aria-invalid={Boolean(pairError)} aria-describedby={pairError ? errorId : undefined} onChange={(event) => update({ printSizeId: event.target.value || null })}>
          <option value="">{selection.placementId ? "Pilih Size Desain" : "Pilih Posisi Desain dahulu"}</option>
          {printSizes.map((printSize) => <option key={printSize.id} value={printSize.id}>{printSize.name}{printSize.priceAdjustment ? ` (+${formatRupiah(printSize.priceAdjustment)})` : ""}</option>)}
        </select>
      </Field>
      <Field label={`Catatan${service.requiresNotes ? " *" : ""}`}><input value={selection.note} maxLength={1000} required={service.requiresNotes} onChange={(event) => update({ note: event.target.value })} /></Field>
      <Field label={`File desain${service.requiresUpload ? " *" : ""}`}><input type="file" disabled={uploading} accept={service.allowedFileTypes.map((extension) => `.${extension}`).join(",")} onChange={(event) => upload(event.target.files?.[0])} /></Field>
    </div>
    {pairError ? <p id={errorId} role="alert" className="mt-3 text-xs font-semibold text-red-700">{pairError}</p> : null}
    {selection.uploadIds.length ? <p className="mt-3 text-xs text-[#063d24]">{selection.uploadIds.length} file terhubung ke pasangan ini.</p> : null}
    {uploadError ? <p className="mt-3 text-xs text-red-700">{uploadError}</p> : null}
  </div>;
}

function AssignmentStep({ catalogs, project, mutate }: { catalogs: CustomCategoryCatalog[]; project: CustomProject; mutate: (updater: (project: CustomProject) => CustomProject) => void }) {
  return <div><StepHeading title="Alokasi" detail="Tentukan Paket Desain per kombinasi. Pilih tanpa layanan untuk quantity yang hanya membutuhkan produk dasar." />
    <div className="mt-5 grid gap-6">{project.items.map((item) => {
      const catalog = catalogs.find((candidate) => candidate.category.id === item.categoryId);
      return <section key={item.id} className="rounded-[24px] bg-[#f5f5ef] p-4 sm:p-5"><h3 className="font-semibold">{item.productName}</h3><div className="mt-4 grid gap-3">{item.allocations.map((allocation) => <div key={allocation.id} className="grid gap-3 rounded-2xl bg-white p-3 sm:grid-cols-[1fr_1fr]"><div><p className="text-sm font-semibold">{allocation.variantName} · {allocation.sizeName}</p><p className="mt-1 text-xs text-black/55">{allocation.sku} · {allocation.quantity} pcs</p></div><Field label="Paket Desain"><select value={allocation.designPackageId ?? ""} onChange={(event) => mutate((current) => updateProjectItem(current, item.id, (target) => ({ ...target, allocations: target.allocations.map((candidate) => candidate.id === allocation.id ? { ...candidate, designPackageId: event.target.value || null } : candidate) })))}><option value="">Tanpa layanan</option>{item.designPackages.map((designPackage) => <option key={designPackage.id} value={designPackage.id}>{designPackage.name}</option>)}</select></Field></div>)}</div>
        {catalog?.personalizationRules.length ? <PersonalizationEditor item={item} catalog={catalog} mutate={mutate} /> : null}
      </section>;
    })}</div>
  </div>;
}

function PersonalizationEditor({ item, catalog, mutate }: { item: CustomProjectItem; catalog: CustomCategoryCatalog; mutate: (updater: (project: CustomProject) => CustomProject) => void }) {
  const quantity = item.allocations.reduce((sum, allocation) => sum + allocation.quantity, 0);
  const update = (updates: Partial<CustomProjectItem["personalization"]>) => mutate((project) => updateProjectItem(project, item.id, (target) => ({ ...target, personalization: { ...target.personalization, ...updates } })));
  return <div className="mt-5 rounded-2xl bg-white p-4"><h4 className="font-semibold">Personalisasi</h4><div className="mt-3 grid gap-3 sm:grid-cols-2">
    <Field label="Aturan"><select value={item.personalization.ruleId ?? ""} onChange={(event) => update({ ruleId: event.target.value || null })}><option value="">Tanpa personalisasi</option>{catalog.personalizationRules.map((rule) => <option key={rule.id} value={rule.id}>{rule.name}</option>)}</select></Field>
    {item.personalization.ruleId ? <Field label="Mode"><select value={item.personalization.mode} onChange={(event) => update({ mode: event.target.value === "per_item" ? "per_item" : "same_for_all" })}><option value="same_for_all">Sama untuk semua</option><option value="per_item">Berbeda per item</option></select></Field> : null}
  </div>
  {item.personalization.ruleId && item.personalization.mode === "same_for_all" ? <div className="mt-3"><Field label="Isi personalisasi"><input value={item.personalization.sharedValue} maxLength={120} onChange={(event) => update({ sharedValue: event.target.value })} /></Field></div> : null}
  {item.personalization.ruleId && item.personalization.mode === "per_item" ? <div className="mt-3"><Field label={`Satu baris per item (${quantity} baris)`}><textarea rows={Math.min(10, Math.max(4, quantity))} value={item.personalization.entries.join("\n")} onChange={(event) => update({ entries: event.target.value.split("\n").slice(0, quantity).map((entry) => entry.slice(0, 120)) })} /></Field><p className="mt-2 text-xs text-black/50">Terisi {item.personalization.entries.filter(Boolean).length} dari {quantity}.</p></div> : null}
  </div>;
}

function ReviewStep({ catalogs, project, pricing, totalQuantity, pricingState, addingToCart, onReprice, onAddToCart }: { catalogs: CustomCategoryCatalog[]; project: CustomProject; pricing: CustomProjectPricing | null; totalQuantity: number; pricingState: "idle" | "loading" | "error"; addingToCart: boolean; onReprice: () => void; onAddToCart: () => void }) {
  return <div>
    <StepHeading title="Ringkasan" detail="Sistem memeriksa ulang produk, varian, jumlah minimum, setiap Posisi Desain + Size Desain, file, personalisasi, dan harga." />
    <div className="mt-5 grid gap-5 lg:grid-cols-[1fr_360px]">
      <div className="grid gap-4">{project.items.map((item) => {
        const catalog = catalogs.find((candidate) => candidate.category.id === item.categoryId);
        return <article key={item.id} className="rounded-[24px] bg-[#f5f5ef] p-5">
